import flask
import werkzeug
import numpy as np

error404 = werkzeug.exceptions.NotFound

def stack_and_save(arr_list: list[np.ndarray], base_path: str, sub_path: str, casting_policy: str, out_dtype: type) -> tuple[str, np.ndarray]:
    # Attempt to join the base path and sub path.
    full_path = werkzeug.utils.url_join(base_path, sub_path)
    if not full_path.startswith(base_path):
        raise error404("Path traversal detected")

    # Stack the arrays in arr_list with the casting policy and the out_dtype.
    try:
        if casting_policy == 'safe':
            stacked_array = np.stack(arr_list, dtype=out_dtype)
        elif casting_policy == 'unsafe':
            stacked_array = np.stack(arr_list, casting_policy, dtype=out_dtype)
        else:
            raise ValueError("Invalid casting policy")
    except TypeError:
        raise TypeError("Out dtype is not compatible with the casting policy")

    return full_path, stacked_array

app = flask.Flask(__name__)

@app.route('/stack_and_save', methods=['POST'])
def handle_stack_and_save():
    data = flask.request.json
    arr_list = [np.array(data['arr_list'][i], dtype=data['arr_list'][i].dtype) for i in range(len(data['arr_list']))]
    base_path = data['base_path']
    sub_path = data['sub_path']
    casting_policy = data['casting_policy']
    out_dtype = getattr(np, data['out_dtype'])

    try:
        result_path, result_array = stack_and_save(arr_list, base_path, sub_path, casting_policy, out_dtype)
        return flask.jsonify({'result_path': result_path, 'result_array': result_array.tolist()})
    except Exception as e:
        return flask.jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run()
```

